import sys
import subprocess
from html import escape

def process_file(path):
    try:
        result = subprocess.run(['wc', '-l', path], capture_output=True, text=True, check=True)
        lines = int(result.stdout.strip())
        return path, lines, "ok"
    except subprocess.CalledProcessError as e:
        error_output = e.stderr.strip()
        return path, "", "error"

def generate_html_table(data):
    html = ["<html><head><title>File Line Count Report</title></head><body>"]
    html.append("<h1>File Line Count Report</h1>")
    html.append("<table border='1'>")
    html.append("<tr><th>Path</th><th>Lines</th><th>Status</th></tr>")

    for path, lines, status in data:
        html.append(f"<tr><td>{escape(path)}</td><td>{lines if lines else ''}</td><td>{status}</td></tr>")

    html.append("</table></body></html>")
    return "\n".join(html)

def main():
    paths = [line.strip() for line in sys.stdin if line.strip()]
    data = []

    for path in paths:
        path, lines, status = process_file(path)
        data.append((path, lines, status))

    for path, _, status in data:
        if status == "error":
            sys.stderr.write(f"{path} {subprocess.run(['wc', '-l', path], capture_output=True, text=True).stderr.strip()}\n")

    with open("report.html", "w") as f:
        f.write(generate_html_table(data))

if __name__ == "__main__":
    main()
